//! Runs every folder under tests/cases, tests/stops and tests/errors (P2R-70 to P2R-74, P2R-76).
//!
//! `PHP2RUST_BLESS=1 cargo test --test folders` rewrites every expected.rs and expected.txt
//! from the current tool output. CI never sets it.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};
use std::sync::OnceLock;

const HEADER: &str =
    "// Generated by php2rust. In release builds set overflow-checks = true, see the README.\n";

fn bless() -> bool {
    std::env::var_os("PHP2RUST_BLESS").is_some()
}

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn name(dir: &Path) -> String {
    dir.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_owned()
}

fn text(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

fn folders(kind: &str) -> Vec<PathBuf> {
    let Ok(entries) = fs::read_dir(root().join("tests").join(kind)) else {
        return Vec::new();
    };
    let mut dirs: Vec<PathBuf> = entries
        .map(|entry| entry.expect("readable test folder").path())
        .filter(|path| path.is_dir())
        .collect();
    dirs.sort();
    dirs
}

fn run(program: &str, args: &[&str], dir: &Path) -> Output {
    Command::new(program)
        .args(args)
        .current_dir(dir)
        .output()
        .unwrap_or_else(|err| panic!("cannot run {program}: {err}"))
}

fn tool(args: &[&str], dir: &Path) -> Output {
    run(env!("CARGO_BIN_EXE_php2rust"), args, dir)
}

/// Fails loudly when a tool the checks need is missing or has the wrong version: a skipped
/// behaviour check looks exactly like a pass.
fn check_toolchain() {
    let rustc = text(&run("rustc", &["--version"], &root()).stdout);
    assert!(
        rustc.starts_with("rustc 1.99.0 "),
        "the tests need the pinned rustc 1.99.0, found: {rustc}"
    );
    let rustfmt = run("rustfmt", &["--version"], &root());
    assert!(
        rustfmt.status.success(),
        "rustfmt is missing: {}",
        text(&rustfmt.stderr)
    );
    // `rustc 1.99.0 (b940084d7e 2026-..)`: the expected files are this rustfmt's layout
    // (P2R-83, P2R-190).
    let commit = rustc.split(['(', ' ']).nth(3).unwrap_or_default();
    let rustfmt = text(&rustfmt.stdout);
    assert!(
        !commit.is_empty() && rustfmt.contains(commit),
        "the tests need the rustfmt of the pinned rustc ({commit}), found: {rustfmt}"
    );
    let php = text(&run("php", &["-n", "-r", "echo PHP_VERSION;"], &root()).stdout);
    assert!(
        php.starts_with("8.5."),
        "the tests need PHP 8.5, found: {php}"
    );
    let mut probe = php_flags();
    probe.extend(["-r", "echo function_exists('ctype_digit') ? 'yes' : 'no';"]);
    let ctype = run("php", &probe, &root());
    assert!(
        ctype.stdout == b"yes" && ctype.stderr.is_empty(),
        "the tests need PHP's ctype functions: {}",
        text(&ctype.stderr)
    );
}

/// The flags of the P2R-72 PHP run. `-n` skips php.ini, and with it a `ctype` that the PHP
/// build loads as a shared extension, as Ubuntu's packages do; that build gets it back
/// with `-d extension=ctype`.
fn php_flags() -> Vec<&'static str> {
    static FLAGS: OnceLock<Vec<&'static str>> = OnceLock::new();
    FLAGS
        .get_or_init(|| {
            let mut flags = vec![
                "-n",
                "-d",
                "display_errors=stderr",
                "-d",
                "error_reporting=E_ALL",
            ];
            let builtin = run(
                "php",
                &[
                    "-n",
                    "-r",
                    "echo function_exists('ctype_digit') ? 'yes' : 'no';",
                ],
                &root(),
            );
            if builtin.stdout != b"yes" {
                flags.extend(["-d", "extension=ctype"]);
            }
            flags
        })
        .clone()
}

#[test]
fn folders_behave_as_the_spec_says() {
    check_toolchain();
    let scratch = std::env::temp_dir().join(format!("php2rust-tests-{}", std::process::id()));
    fs::create_dir_all(&scratch).expect("scratch directory");
    // The empty configuration the tool lays out with, so a `rustfmt.toml` near a folder
    // does not change the check (P2R-190).
    fs::write(scratch.join("rustfmt.toml"), "").expect("empty rustfmt configuration");
    let mut failures: Vec<String> = Vec::new();
    for dir in folders("cases") {
        let result = if dir.join("input").is_dir() {
            crate_case(&dir, &scratch)
        } else {
            case(&dir, &scratch)
        };
        if let Err(why) = result {
            failures.push(format!("cases/{}: {why}", name(&dir)));
        }
    }
    for dir in folders("stops") {
        if let Err(why) = stop(&dir) {
            failures.push(format!("stops/{}: {why}", name(&dir)));
        }
    }
    for dir in folders("errors") {
        if let Err(why) = error(&dir) {
            failures.push(format!("errors/{}: {why}", name(&dir)));
        }
    }
    let _ = fs::remove_dir_all(&scratch);
    assert!(
        failures.is_empty(),
        "{} folder(s) failed:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}

/// `rustfmt --check` of `file`, run in `dir` with the empty configuration in `scratch`
/// (P2R-51, P2R-190).
fn formatted(scratch: &Path, file: &str, dir: &Path) -> Output {
    let config = scratch.join("rustfmt.toml");
    let config = config.to_str().expect("UTF-8 scratch path");
    run(
        "rustfmt",
        &[
            "--edition",
            "2024",
            "--config-path",
            config,
            "--check",
            file,
        ],
        dir,
    )
}

/// P2R-70 to P2R-72: same text, clean Rust, same printed output as PHP.
fn case(dir: &Path, scratch: &Path) -> Result<(), String> {
    let first = tool(&["input.php"], dir);
    if first.status.code() != Some(0) || !first.stderr.is_empty() {
        return Err(format!(
            "exit {:?}, stderr:\n{}",
            first.status.code(),
            text(&first.stderr)
        ));
    }
    if tool(&["input.php"], dir).stdout != first.stdout {
        return Err("two runs gave different output (P2R-06)".into());
    }
    let expected_path = dir.join("expected.rs");
    if bless() {
        fs::write(&expected_path, &first.stdout).map_err(|e| e.to_string())?;
    }
    let expected = fs::read(&expected_path).map_err(|e| format!("expected.rs: {e}"))?;
    if first.stdout != expected {
        return Err(format!(
            "output differs from expected.rs\n-- expected\n{}-- actual\n{}",
            text(&expected),
            text(&first.stdout)
        ));
    }
    let source = text(&expected);
    if !source.starts_with(HEADER) {
        return Err("expected.rs does not start with the P2R-52 line".into());
    }
    let format = formatted(scratch, "expected.rs", dir);
    if !format.status.success() {
        return Err(format!(
            "rustfmt --check failed (P2R-51):\n{}",
            text(&format.stdout)
        ));
    }
    let program = source.lines().any(|line| line == "fn main() {");
    let binary = scratch.join(name(dir));
    let target = binary.to_str().expect("UTF-8 scratch path");
    let mut args = vec!["--edition", "2024", "-D", "warnings", "-o", target];
    if !program {
        args.extend(["--crate-type", "lib"]);
    }
    args.push("expected.rs");
    let build = run("rustc", &args, dir);
    if !build.status.success() {
        return Err(format!("rustc failed (P2R-50):\n{}", text(&build.stderr)));
    }
    if !program {
        return Ok(());
    }
    let mut flags = php_flags();
    flags.push("input.php");
    let php = run("php", &flags, dir);
    if php.status.code() != Some(0) || !php.stderr.is_empty() {
        return Err(format!(
            "PHP run failed, exit {:?}:\n{}",
            php.status.code(),
            text(&php.stderr)
        ));
    }
    let rust = run(target, &[], dir);
    if rust.status.code() != Some(0) {
        return Err(format!(
            "Rust run failed, exit {:?}:\n{}",
            rust.status.code(),
            text(&rust.stderr)
        ));
    }
    if php.stdout.is_empty() {
        return Err("the case prints nothing (P2R-72)".into());
    }
    if php.stdout != rust.stdout {
        return Err(format!(
            "stdout differs\n-- php\n{}-- rust\n{}",
            text(&php.stdout),
            text(&rust.stdout)
        ));
    }
    Ok(())
}

/// P2R-176: a directory `input/` converts to the crate in `expected/`, file by file, twice
/// the same, and the crate passes rustfmt and rustc.
fn crate_case(dir: &Path, scratch: &Path) -> Result<(), String> {
    let out = scratch.join(format!("{}-crate", name(dir)));
    let again = scratch.join(format!("{}-again", name(dir)));
    for target in [&out, &again] {
        let _ = fs::remove_dir_all(target);
        let path = target.to_str().expect("UTF-8 scratch path");
        let result = tool(&["input", "-o", path], dir);
        if result.status.code() != Some(0) || !result.stderr.is_empty() || !result.stdout.is_empty()
        {
            return Err(format!(
                "exit {:?}, stderr:\n{}",
                result.status.code(),
                text(&result.stderr)
            ));
        }
    }
    let written = tree(&out)?;
    if tree(&again)? != written {
        return Err("two runs gave different crates (P2R-06)".into());
    }
    let expected_dir = dir.join("expected");
    if bless() {
        let _ = fs::remove_dir_all(&expected_dir);
        for (path, bytes) in &written {
            let target = expected_dir.join(path);
            fs::create_dir_all(target.parent().expect("a file in a folder"))
                .map_err(|e| e.to_string())?;
            fs::write(target, bytes).map_err(|e| e.to_string())?;
        }
    }
    let expected = tree(&expected_dir)?;
    if written != expected {
        let paths = |files: &BTreeMap<String, Vec<u8>>| files.keys().cloned().collect::<Vec<_>>();
        let changed: Vec<&String> = written
            .iter()
            .filter(|(path, bytes)| expected.get(*path) != Some(bytes))
            .map(|(path, _)| path)
            .collect();
        return Err(format!(
            "crate differs from expected/\n-- expected files {:?}\n-- written files {:?}\n-- changed {changed:?}",
            paths(&expected),
            paths(&written)
        ));
    }
    if let Some((path, _)) = expected
        .iter()
        .find(|(_, bytes)| !bytes.starts_with(HEADER.as_bytes()))
    {
        return Err(format!(
            "expected/{path} does not start with the P2R-52 line"
        ));
    }
    let format = formatted(scratch, "expected/lib.rs", dir);
    if !format.status.success() {
        return Err(format!(
            "rustfmt --check failed (P2R-51):\n{}",
            text(&format.stdout)
        ));
    }
    let library = scratch.join(format!("{}.rlib", name(dir)));
    let target = library.to_str().expect("UTF-8 scratch path");
    let build = run(
        "rustc",
        &[
            "--edition",
            "2024",
            "--crate-type",
            "lib",
            "-D",
            "warnings",
            "-o",
            target,
            "expected/lib.rs",
        ],
        dir,
    );
    if !build.status.success() {
        return Err(format!("rustc failed (P2R-50):\n{}", text(&build.stderr)));
    }
    Ok(())
}

/// Every file under `dir`, by its path below `dir` with `/`, with its bytes.
fn tree(dir: &Path) -> Result<BTreeMap<String, Vec<u8>>, String> {
    fn walk(root: &Path, dir: &Path, files: &mut BTreeMap<String, Vec<u8>>) -> Result<(), String> {
        for entry in fs::read_dir(dir).map_err(|e| format!("{}: {e}", dir.display()))? {
            let path = entry.map_err(|e| e.to_string())?.path();
            if path.is_dir() {
                walk(root, &path, files)?;
            } else {
                let relative = path.strip_prefix(root).expect("below the root");
                let key = relative.to_string_lossy().replace('\\', "/");
                files.insert(key, fs::read(&path).map_err(|e| e.to_string())?);
            }
        }
        Ok(())
    }
    let mut files = BTreeMap::new();
    walk(dir, dir, &mut files)?;
    Ok(files)
}

/// P2R-73: refused with the expected problem lines, nothing written. A stop folder with a
/// directory `input/` runs as `php2rust input -o out` (P2R-176).
fn stop(dir: &Path) -> Result<(), String> {
    if dir.join("input").is_dir() {
        let result = tool(&["input", "-o", "out"], dir);
        let temporary = dir.join("out.php2rust-tmp");
        let created = dir.join("out").exists() || temporary.exists();
        let _ = fs::remove_dir_all(dir.join("out"));
        let _ = fs::remove_dir_all(temporary);
        return stopped(dir, &["input", "-o", "out"], &result, created);
    }
    for args in [&["input.php"][..], &["input.php", "-o", "out.rs"][..]] {
        let result = tool(args, dir);
        let created = dir.join("out.rs").exists();
        let _ = fs::remove_file(dir.join("out.rs"));
        stopped(dir, args, &result, created)?;
    }
    Ok(())
}

/// Checks one stop run: exit 1, `expected.txt` on stderr, nothing on stdout, and no
/// output written (P2R-05, P2R-73).
fn stopped(dir: &Path, args: &[&str], result: &Output, created: bool) -> Result<(), String> {
    if bless() {
        fs::write(dir.join("expected.txt"), &result.stderr).map_err(|e| e.to_string())?;
    }
    let expected =
        fs::read_to_string(dir.join("expected.txt")).map_err(|e| format!("expected.txt: {e}"))?;
    let stderr = text(&result.stderr);
    if result.status.code() != Some(1) {
        return Err(format!(
            "{args:?}: exit {:?}, expected 1\n{stderr}",
            result.status.code()
        ));
    }
    if stderr != expected {
        return Err(format!(
            "{args:?}: stderr differs\n-- expected\n{expected}-- actual\n{stderr}"
        ));
    }
    if !result.stdout.is_empty() {
        return Err(format!("{args:?}: stdout is not empty (P2R-05)"));
    }
    if created {
        return Err(format!("{args:?}: the output was created (P2R-05)"));
    }
    Ok(())
}

/// P2R-74: exit 2 with the expected reason, every file in the folder unchanged.
fn error(dir: &Path) -> Result<(), String> {
    let args_text =
        fs::read_to_string(dir.join("args.txt")).map_err(|e| format!("args.txt: {e}"))?;
    let args: Vec<&str> = args_text.lines().collect();
    let before = snapshot(dir)?;
    let result = tool(&args, dir);
    let after = snapshot(dir)?;
    if bless() {
        fs::write(dir.join("expected.txt"), &result.stderr).map_err(|e| e.to_string())?;
    }
    let expected =
        fs::read_to_string(dir.join("expected.txt")).map_err(|e| format!("expected.txt: {e}"))?;
    let stderr = text(&result.stderr);
    if result.status.code() != Some(2) {
        return Err(format!(
            "exit {:?}, expected 2\n{stderr}",
            result.status.code()
        ));
    }
    if stderr != expected {
        return Err(format!(
            "stderr differs\n-- expected\n{expected}-- actual\n{stderr}"
        ));
    }
    if !result.stdout.is_empty() {
        return Err("stdout is not empty (P2R-05)".into());
    }
    if before != after {
        return Err("files in the folder changed (P2R-74)".into());
    }
    Ok(())
}

/// Every file in the folder and below it except expected.txt, by path, with its bytes; a
/// directory counts as an empty entry, so one the run creates shows (P2R-74, P2R-176).
fn snapshot(dir: &Path) -> Result<BTreeMap<String, Vec<u8>>, String> {
    let mut files = tree(dir)?;
    files.remove("expected.txt");
    for entry in fs::read_dir(dir).map_err(|e| e.to_string())? {
        let path = entry.map_err(|e| e.to_string())?.path();
        if path.is_dir() {
            files.insert(format!("{}/", name(&path)), Vec::new());
        }
    }
    Ok(files)
}
